import { rockDefaults } from '../src/domain/rocks.js';

/** Original metric rock meshes, generated by the same runtime used in the editor. */
export function addMountainLibrary({add,timeless}) {
  const model=(id,name,size,extras=[],description='')=>{
    const defaults=rockDefaults(`builtin-${id}`);
    const part=(size,position,seedOffset=0,rotation)=>({shape:'rock',size,position,material:'stone',...defaults,seed:(defaults.seed+seedOffset)%65536,seedOffset,...(rotation?{rotation}: {})});
    add(id,name,'Exterior / Montanha',timeless,['Montanha','Ruínas','Floresta'],['rocha','montanha','pedra','geologia',...(id==='stratified-cliff'?['paredão','estratos']:[])],
      [part(size,[0,0,0]),...extras.map(([dimensions,position,offset,rotation])=>part(dimensions,position,offset,rotation))],description);
  };
  model('mountain-boulder','Rocha fraturada',[2.6,2,2],[[[.9,.65,.8],[1.25,0,.6],9]],'Rocha com faces quebradas e volume irregular. Forma, irregularidade, detalhe e seed editáveis no inspetor.');
  model('granite-boulder','Matacão de granito',[3,2.2,2.5],[[[.8,.6,.7],[-1.3,0,.6],13]],'Matacão arredondado com saliências e depressões; base métrica. Aplique granito no material de rocha natural.');
  model('stratified-cliff','Paredão estratificado',[5,6,2.6],[[[1.8,2.4,1.6],[-2,.0,.7],7],[[2.2,1.5,1.9],[1.7,0,.9],19]],'Paredão com camadas e saliências reais. Combine peças por rotação/escala para compor um desfiladeiro.');
  model('rock-scree','Entulho rochoso',[1.1,.65,.9],Array.from({length:8},(_,i)=>{
    const a=i*Math.PI*2/8,r=.5+(i%3)*.27;
    return [[.35+(i%3)*.17,.25+(i%2)*.2,.35+(i%4)*.09],[Math.cos(a)*r,0,Math.sin(a)*r],i*11+3,[0,a,i%2*.15]];
  }),'Conjunto de pedras irregulares para bordas de trilhas e ruínas. Sem espalhamento automático.');
}
